/**
 * Official Payment App Brand Assets & Configuration
 * Sourced according to brand guidelines and verified vector representations.
 */

export interface PaymentBrandAsset {
  id: string;
  name: string;
  path: string;
  aspectRatio: number;
  dataUrl: string;
}

export const PAYMENT_BRAND_ASSETS: PaymentBrandAsset[] = [
  {
    id: "google-pay",
    name: "Google Pay",
    path: "/payment-apps/google-pay/google-pay.svg",
    aspectRatio: 2.6667,
    dataUrl: "data:image/svg+xml;base64,",
  },
  {
    id: "phonepe",
    name: "PhonePe",
    path: "/payment-apps/phonepe/phonepe.svg",
    aspectRatio: 3.2975,
    dataUrl: "data:image/svg+xml;base64,",
  },
  {
    id: "paytm",
    name: "Paytm",
    path: "/payment-apps/paytm/paytm.svg",
    aspectRatio: 3.186,
    dataUrl: "data:image/svg+xml;base64,",
  },
  {
    id: "bhim",
    name: "BHIM",
    path: "/payment-apps/bhim/bhim.svg",
    aspectRatio: 4.043,
    dataUrl: "data:image/svg+xml;base64,",
  },
  {
    id: "upi",
    name: "UPI",
    path: "/payment-apps/upi/upi.svg",
    aspectRatio: 2.8297,
    dataUrl: "data:image/svg+xml;base64,",
  },
];

/**
 * Preload payment brand assets as HTMLImageElements for canvas drawing.
 */
export async function loadPaymentBrandImages(): Promise<Map<string, HTMLImageElement>> {
  const map = new Map<string, HTMLImageElement>();
  if (typeof window === "undefined") return map;

  const loadPromises = PAYMENT_BRAND_ASSETS.map((asset) => {
    return new Promise<void>((resolve) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => {
        map.set(asset.id, img);
        resolve();
      };
      img.onerror = () => {
        resolve();
      };
      img.src = asset.dataUrl;
    });
  });

  await Promise.all(loadPromises);
  return map;
}
